(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cfg=null,registry=null,modal=null,bound=false,activeId=null,localeHint=null;
const locale=()=>String(localeHint||localStorage.getItem('lri_locale')||document.documentElement.lang||'zh').toLowerCase();
const isEn=()=>locale().startsWith('en');
const L=(zh,en)=>isEn()?en:zh;
const pick=(o,key)=>{const en=o?.[`${key}_en`];return isEn()&&en!=null?en:o?.[key]};
const list=(o,key)=>{const en=o?.[`${key}_en`];return isEn()&&Array.isArray(en)?en:(o?.[key]||[])};
const ensure=()=>{if(modal)return modal;const h=document.createElement('div');h.className='lri-theory-modal-root';h.innerHTML=`<div class="lri-theory-backdrop" data-theory-close></div><section class="lri-theory-modal" role="dialog" aria-modal="true"><button class="lri-theory-close" data-theory-close aria-label="Close">×</button><div class="lri-theory-scroll"></div></section>`;document.body.appendChild(h);modal=h;h.addEventListener('click',e=>{if(e.target.closest('[data-theory-close]'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&h.classList.contains('open'))close()});return h};
const close=()=>{modal?.classList.remove('open');document.documentElement.classList.remove('lri-theory-modal-open');activeId=null};
const view=t=>{const runtime=globalThis.LRIVisualProfile||globalThis.LRISignalVisual;if(!runtime?.profile)throw new Error(L('视觉 Profile Runtime 不可用','Visual Profile Runtime is unavailable'));const v=runtime.profile(t,'compact_card'),b=v.byId;return{profile:v.name,schema:t.visual_grammar?.schema||'unknown',hero:b.hero||{},principle:b.principle||{},mechanism:b.mechanism||{},explanation:b.explanation||{},boundary:b.boundary||{},provenance:b.provenance||{}}};
const render=async id=>{const h=ensure(),box=h.querySelector('.lri-theory-scroll');box.innerHTML=`<div class="lri-theory-loading">${esc(L('加载中…','Loading…'))}</div>`;registry=registry||await(await fetch(cfg.registryUrl,{cache:'no-store'})).json();const t=(registry.items||[]).find(x=>x.id===id);if(!t)throw new Error(L('未找到理论卡','Theory card not found'));const v=view(t),hero=v.hero,principle=v.principle,mechanism=v.mechanism,explanation=v.explanation,boundary=v.boundary,provenance=v.provenance;const mechanisms=list(mechanism,'items'),boundaries=list(boundary,'items');box.innerHTML=`<article class="lri-theory-sheet" data-visual-profile="${esc(v.profile)}" data-visual-schema="${esc(v.schema)}" data-theory-id="${esc(t.id)}"><header><span>THEORY EVIDENCE · ${esc(pick(hero,'category'))}</span><h2>${esc(pick(hero,'title'))}</h2><p>${esc(pick(hero,'subtitle'))}</p></header><div class="lri-theory-body-grid"><section class="lri-theory-left"><div class="lri-theory-principle"><b>${esc(L('核心原理','Core principle'))}</b><p>${esc(pick(principle,'text'))}</p><div class="lri-theory-formula">${esc(principle.formula)}</div></div><div class="lri-theory-explains"><b>${esc(L('为什么能解释本月信号','Why it explains current signals'))}</b><p>${esc(pick(explanation,'text'))}</p></div></section><section class="lri-theory-right"><div class="lri-theory-flow">${mechanisms.map((x,i)=>`<article><span>${i+1}</span><p>${esc(x)}</p></article>`).join('')}</div><div class="lri-theory-boundary"><b>${esc(L('理论边界','Theory boundary'))}</b><ul>${boundaries.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></section></div><footer>${(provenance.items||[]).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title)} · ${esc(s.year)} ↗</a>`).join('')}</footer></article>`};
const open=async id=>{if(!cfg)return;activeId=id;const h=ensure();h.classList.add('open');document.documentElement.classList.add('lri-theory-modal-open');try{await render(id)}catch(e){h.querySelector('.lri-theory-scroll').innerHTML=`<div class="lri-theory-loading">${esc(L('理论卡加载失败','Theory card failed to load'))}：${esc(e.message)}</div>`}};
const configure=o=>{cfg=o;registry=null;return api};const bind=(r=document)=>{if(bound)return api;bound=true;r.addEventListener('click',e=>{const el=e.target.closest('[data-theory-id]');if(!el)return;e.preventDefault();open(el.dataset.theoryId)});return api};
document.addEventListener('lri:locale-change',e=>{localeHint=e.detail?.locale||null;if(activeId&&modal?.classList.contains('open'))open(activeId)});
const api={configure,bind,open,close};globalThis.LRITheoryModal=api;
})();

